A csatolt `main-32.py` és `file-1.html` alapján az alábbiakban egy egymással kompatibilis, éles környezetre szánt backend+frontend teljes kódját küldöm, a frontend által hívott endpointokkal és a backend által biztosított SSE-kutatás folyamattal összhangban.[1][2]

- `main.py`
```python
import os
import json
import uuid
import time
import queue
import base64
import hashlib
import secrets
import threading
import mimetypes
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from typing import Any, Dict, List, Optional, Tuple, Iterable, Callable

import requests
import redis

from flask import Flask, Response, abort, jsonify, redirect, request, send_from_directory, session, stream_with_context
from flask_cors import CORS
from flask_session import Session

APP_NAME = "tiffytime"
UPLOAD_FOLDER = os.environ.get("UPLOAD_FOLDER", "uploads")
os.makedirs(UPLOAD_FOLDER, exist_ok=True)

DEFAULT_HTTP_TIMEOUT = float(os.environ.get("DEFAULT_HTTP_TIMEOUT", "30"))
SSE_MAX_CLIENTS_PER_SESSION = int(os.environ.get("SSE_MAX_CLIENTS_PER_SESSION", "10"))
MAX_UPLOAD_BYTES = int(os.environ.get("MAX_UPLOAD_BYTES", str(100 * 1024 * 1024)))
MAX_MESSAGE_CHARS = int(os.environ.get("MAX_MESSAGE_CHARS", "10000"))
MAX_GOAL_CHARS = int(os.environ.get("MAX_GOAL_CHARS", "5000"))
CHAT_HISTORY_LIMIT = int(os.environ.get("CHAT_HISTORY_LIMIT", "40"))
CONVERSATIONS_LIMIT = int(os.environ.get("CONVERSATIONS_LIMIT", "100"))

EXA_API_KEY = os.environ.get("EXA_API_KEY", "")
XAI_API_KEY = os.environ.get("XAI_API_KEY", "")
CEREBRAS_API_KEY = os.environ.get("CEREBRAS_API_KEY", "")

KINDE_HOST = os.environ.get("KINDE_HOST", "")
KINDE_CLIENT_ID = os.environ.get("KINDE_CLIENT_ID", "")
KINDE_CLIENT_SECRET = os.environ.get("KINDE_CLIENT_SECRET", "")
KINDE_REDIRECT_URI = os.environ.get("KINDE_REDIRECT_URI", "")

ALLOW_GUEST = os.environ.get("ALLOW_GUEST", "true").lower() == "true"

SESSION_SECRET = os.environ.get("SESSION_SECRET", "")
if not SESSION_SECRET:
    SESSION_SECRET = secrets.token_hex(32)

COOKIE_SECURE = os.environ.get("COOKIE_SECURE", "false").lower() == "true"
COOKIE_SAMESITE = os.environ.get("COOKIE_SAMESITE", "Lax")
COOKIE_HTTPONLY = True

ALLOWED_ORIGINS_RAW = os.environ.get("ALLOWED_ORIGINS", "*")
ALLOWED_ORIGINS = [o.strip() for o in ALLOWED_ORIGINS_RAW.split(",") if o.strip()] or ["*"]

REDIS_URL = os.environ.get("DRAGONFLY_URL", os.environ.get("REDIS_URL", ""))
REDIS_HOST = os.environ.get("DRAGONFLY_HOST", "")
REDIS_PORT = os.environ.get("DRAGONFLY_PORT", "")
REDIS_PASSWORD = os.environ.get("DRAGONFLY_PASSWORD", os.environ.get("REDIS_PASSWORD", ""))

XAI_BASE_URL = os.environ.get("XAI_BASE_URL", "")
XAI_CHAT_PATH = os.environ.get("XAI_CHAT_PATH", "/chat/completions")
XAI_MODEL_FAST = os.environ.get("XAI_MODEL_FAST", "grok-4-1-fast")
XAI_MODEL_PRO = os.environ.get("XAI_MODEL_PRO", "grok-4-latest")

CEREBRAS_MODEL_FAST = os.environ.get("CEREBRAS_MODEL_FAST", "gpt-oss-120b")

EXA_BASE_URL = os.environ.get("EXA_BASE_URL", "")
EXA_SEARCH_PATH = os.environ.get("EXA_SEARCH_PATH", "/search")
EXA_CONTENTS_PATH = os.environ.get("EXA_CONTENTS_PATH", "/contents")
EXA_FIND_SIMILAR_PATH = os.environ.get("EXA_FIND_SIMILAR_PATH", "/findSimilar")
EXA_ANSWER_PATH = os.environ.get("EXA_ANSWER_PATH", "/answer")

FIXED_SEARCH_HITS = 100

RATE_LIMIT_ENABLED = os.environ.get("RATE_LIMIT_ENABLED", "true").lower() == "true"
RATE_LIMIT_FREE_PER_DAY = int(os.environ.get("RATE_LIMIT_FREE_PER_DAY", "20"))
RATE_LIMIT_PRO_PER_DAY = int(os.environ.get("RATE_LIMIT_PRO_PER_DAY", "300"))
RATE_LIMIT_WINDOW_SECONDS = 24 * 60 * 60

STATE_LOCK = threading.RLock()
SSE_LOCK = threading.RLock()
CLEANUP_LOCK = threading.Lock()

SSE_CLIENTS: Dict[str, List[queue.Queue]] = {}
INMEM_CONVERSATIONS: Dict[str, Dict[str, Any]] = {}
INMEM_RESEARCH: Dict[str, Dict[str, Any]] = {}

CLEANUP_INTERVAL_SECONDS = int(os.environ.get("CLEANUP_INTERVAL_SECONDS", "3600"))
SESSION_TTL_SECONDS = int(os.environ.get("SESSION_TTL_SECONDS", str(365 * 24 * 60 * 60)))
_LAST_CLEANUP_TS = 0.0

ALLOWED_FILENAME_CHARS = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.")
def secure_filename(name: str) -> str:
    name = str(name or "")
    name = os.path.basename(name)
    filtered = "".join([c for c in name if c in ALLOWED_FILENAME_CHARS])
    if not filtered or filtered.startswith("."):
        filtered = "file_" + filtered.lstrip(".")
    return filtered[:255]

def now_iso() -> str:
    return datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

def clamp_int(x: Any, lo: int, hi: int, default: int) -> int:
    try:
        v = int(x)
    except Exception:
        return default
    return max(lo, min(hi, v))

def clamp_float(x: Any, lo: float, hi: float, default: float) -> float:
    try:
        v = float(x)
    except Exception:
        return default
    return max(lo, min(hi, v))

def json_dumps(obj: Any) -> str:
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"))

def sse_pack(data: Dict[str, Any]) -> str:
    return f"data: {json_dumps(data)}\n\n"

def sha256_hex(s: str) -> str:
    return hashlib.sha256(s.encode("utf-8", errors="ignore")).hexdigest()

def b64url(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).decode("utf-8").rstrip("=")

def timing_safe_equal(a: str, b: str) -> bool:
    try:
        return secrets.compare_digest(a, b)
    except Exception:
        return False

def make_id(prefix: str = "") -> str:
    return f"{prefix}{uuid.uuid4().hex}"

def file_read_limited(fp: str, limit: int) -> str:
    try:
        with open(fp, "rb") as f:
            data = f.read(limit + 1)
        if len(data) > limit:
            data = data[:limit]
        try:
            return data.decode("utf-8", errors="ignore")
        except Exception:
            return ""
    except Exception:
        return ""

def guess_mime(path: str) -> str:
    m, _ = mimetypes.guess_type(path)
    return m or "application/octet-stream"

def parse_redis_url(url: str) -> Optional[Dict[str, Any]]:
    url = (url or "").strip()
    if not url:
        return None
    if "://" not in url:
        return None
    try:
        from urllib.parse import urlparse
        p = urlparse(url)
        host = p.hostname or ""
        port = p.port or 6379
        password = p.password or ""
        db = int((p.path or "").lstrip("/") or "0")
        ssl = (p.scheme or "").lower() in ("rediss",)
        if not host:
            return None
        return {"host": host, "port": port, "password": password, "db": db, "ssl": ssl}
    except Exception:
        return None

def create_redis_client() -> Optional[redis.Redis]:
    cfg = parse_redis_url(REDIS_URL)
    host = ""
    port = 0
    password = ""
    db = 0
    ssl = True
    if cfg:
        host = cfg["host"]
        port = int(cfg["port"])
        password = cfg.get("password", "") or REDIS_PASSWORD
        db = int(cfg.get("db", 0))
        ssl = bool(cfg.get("ssl", True))
    else:
        host = (REDIS_HOST or REDIS_URL or "").strip()
        port = int(REDIS_PORT.strip()) if str(REDIS_PORT).strip().isdigit() else 6385
        password = REDIS_PASSWORD
        db = 0
        ssl = True
        if host.startswith("redis://") or host.startswith("rediss://"):
            cfg2 = parse_redis_url(host)
            if cfg2:
                host = cfg2["host"]
                port = int(cfg2["port"])
                password = cfg2.get("password", "") or password
                db = int(cfg2.get("db", 0))
                ssl = bool(cfg2.get("ssl", True))
    host = (host or "").strip()
    if not host:
        return None
    try:
        client = redis.Redis(
            host=host,
            port=port,
            password=password or None,
            db=db,
            ssl=ssl,
            ssl_cert_reqs=None,
            socket_timeout=10,
            socket_connect_timeout=10,
            health_check_interval=30,
            decode_responses=False,
        )
        client.ping()
        return client
    except Exception:
        return None

REDIS_CLIENT = create_redis_client()

def redis_get_json(key: str) -> Optional[Dict[str, Any]]:
    if not REDIS_CLIENT:
        return None
    try:
        raw = REDIS_CLIENT.get(key)
        if not raw:
            return None
        if isinstance(raw, bytes):
            raw = raw.decode("utf-8", errors="ignore")
        if not isinstance(raw, str):
            raw = str(raw)
        return json.loads(raw)
    except Exception:
        return None

def redis_set_json(key: str, obj: Dict[str, Any], ttl: int) -> bool:
    if not REDIS_CLIENT:
        return False
    try:
        REDIS_CLIENT.setex(key, ttl, json_dumps(obj).encode("utf-8"))
        return True
    except Exception:
        return False

def redis_del(key: str) -> bool:
    if not REDIS_CLIENT:
        return False
    try:
        REDIS_CLIENT.delete(key)
        return True
    except Exception:
        return False

def redis_sadd(key: str, member: str, ttl: int) -> bool:
    if not REDIS_CLIENT:
        return False
    try:
        REDIS_CLIENT.sadd(key, member)
        REDIS_CLIENT.expire(key, ttl)
        return True
    except Exception:
        return False

def redis_srem(key: str, member: str) -> bool:
    if not REDIS_CLIENT:
        return False
    try:
        REDIS_CLIENT.srem(key, member)
        return True
    except Exception:
        return False

def redis_smembers(key: str) -> List[str]:
    if not REDIS_CLIENT:
        return []
    try:
        raw = REDIS_CLIENT.smembers(key)
        out: List[str] = []
        for x in raw:
            if isinstance(x, bytes):
                out.append(x.decode("utf-8", errors="ignore"))
            else:
                out.append(str(x))
        return out
    except Exception:
        return []

def redis_incr(key: str, ttl: int) -> int:
    if not REDIS_CLIENT:
        return 0
    try:
        v = int(REDIS_CLIENT.incr(key))
        if v == 1:
            REDIS_CLIENT.expire(key, ttl)
        return v
    except Exception:
        return 0

def ensure_user() -> Optional[Dict[str, Any]]:
    u = session.get("user")
    if isinstance(u, dict) and u.get("id"):
        return u
    return None

def require_user() -> Optional[Response]:
    u = ensure_user()
    if u:
        return None
    return jsonify({"error": "Unauthorized", "code": "NOT_AUTHENTICATED"}), 401

def is_pro_user(user: Dict[str, Any]) -> bool:
    if not user:
        return False
    if user.get("plan") == "pro":
        return True
    if user.get("is_guest"):
        return False
    return bool(os.environ.get("DEFAULT_USERS_PRO", "false").lower() == "true")

def rate_limit_check(user: Dict[str, Any]) -> Tuple[bool, int, int]:
    if not RATE_LIMIT_ENABLED or not REDIS_CLIENT:
        return True, 0, 0
    uid = user.get("id", "")
    if not uid:
        return True, 0, 0
    limit = RATE_LIMIT_PRO_PER_DAY if is_pro_user(user) else RATE_LIMIT_FREE_PER_DAY
    key = f"{APP_NAME}:rate:{uid}:{datetime.utcnow().strftime('%Y%m%d')}"
    used = redis_incr(key, RATE_LIMIT_WINDOW_SECONDS)
    remaining = max(0, limit - used)
    allowed = used <= limit
    return allowed, remaining, limit

def broadcast_sse(session_id: str, payload: Dict[str, Any]) -> None:
    if not session_id:
        return
    evt = dict(payload)
    evt["timestamp"] = now_iso()
    with SSE_LOCK:
        qs = SSE_CLIENTS.get(session_id, [])
        if not qs:
            return
        for q in list(qs):
            try:
                q.put_nowait(evt)
            except Exception:
                pass

def sse_register(session_id: str) -> Optional[queue.Queue]:
    if not session_id:
        return None
    q: queue.Queue = queue.Queue(maxsize=2000)
    with SSE_LOCK:
        cur = SSE_CLIENTS.get(session_id, [])
        if len(cur) >= SSE_MAX_CLIENTS_PER_SESSION:
            return None
        cur.append(q)
        SSE_CLIENTS[session_id] = cur
    return q

def sse_unregister(session_id: str, q: queue.Queue) -> None:
    with SSE_LOCK:
        cur = SSE_CLIENTS.get(session_id, [])
        if not cur:
            return
        nxt = [x for x in cur if x is not q]
        if nxt:
            SSE_CLIENTS[session_id] = nxt
        else:
            SSE_CLIENTS.pop(session_id, None)

def cleanup_tick() -> None:
    global _LAST_CLEANUP_TS
    now = time.time()
    if now - _LAST_CLEANUP_TS < CLEANUP_INTERVAL_SECONDS:
        return
    with CLEANUP_LOCK:
        now2 = time.time()
        if now2 - _LAST_CLEANUP_TS < CLEANUP_INTERVAL_SECONDS:
            return
        _LAST_CLEANUP_TS = now2
        with STATE_LOCK:
            expired = []
            for sid, obj in list(INMEM_RESEARCH.items()):
                ts = obj.get("created_at_ts", 0.0)
                if ts and (now2 - ts) > SESSION_TTL_SECONDS:
                    expired.append(sid)
            for sid in expired:
                INMEM_RESEARCH.pop(sid, None)
                with SSE_LOCK:
                    SSE_CLIENTS.pop(sid, None)

def conv_key(conv_id: str) -> str:
    return f"{APP_NAME}:conv:{conv_id}"

def user_convs_key(user_id: str) -> str:
    return f"{APP_NAME}:user_convs:{user_id}"

def research_key(sid: str) -> str:
    return f"{APP_NAME}:research:{sid}"

def user_research_key(user_id: str) -> str:
    return f"{APP_NAME}:user_research:{user_id}"

def share_key(token: str) -> str:
    return f"{APP_NAME}:share:{token}"

def load_conversation(conv_id: str) -> Optional[Dict[str, Any]]:
    if not conv_id:
        return None
    if REDIS_CLIENT:
        obj = redis_get_json(conv_key(conv_id))
        if obj:
            return obj
    with STATE_LOCK:
        return INMEM_CONVERSATIONS.get(conv_id)

def save_conversation(conv: Dict[str, Any]) -> None:
    if not isinstance(conv, dict):
        return
    conv_id = conv.get("id", "")
    user_id = conv.get("user_id", "")
    if not conv_id or not user_id:
        return
    conv["updated_at"] = now_iso()
    if REDIS_CLIENT:
        redis_set_json(conv_key(conv_id), conv, SESSION_TTL_SECONDS)
        redis_sadd(user_convs_key(user_id), conv_id, SESSION_TTL_SECONDS)
    with STATE_LOCK:
        INMEM_CONVERSATIONS[conv_id] = conv

def delete_conversation(conv_id: str, user_id: str) -> bool:
    ok = False
    if REDIS_CLIENT:
        ok = redis_del(conv_key(conv_id))
        redis_srem(user_convs_key(user_id), conv_id)
    with STATE_LOCK:
        if conv_id in INMEM_CONVERSATIONS:
            del INMEM_CONVERSATIONS[conv_id]
            ok = True
    return ok

def list_user_conversations(user_id: str) -> List[Dict[str, Any]]:
    convs: Dict[str, Dict[str, Any]] = {}
    if REDIS_CLIENT:
        ids = redis_smembers(user_convs_key(user_id))
        for cid in ids:
            obj = redis_get_json(conv_key(cid))
            if obj and obj.get("user_id") == user_id:
                convs[cid] = obj
    with STATE_LOCK:
        for cid, c in INMEM_CONVERSATIONS.items():
            if c.get("user_id") == user_id and cid not in convs:
                convs[cid] = c
    out = list(convs.values())
    def keyfn(x: Dict[str, Any]) -> str:
        return str(x.get("updated_at") or x.get("created_at") or "")
    out.sort(key=keyfn, reverse=True)
    return out[:CONVERSATIONS_LIMIT]

def load_research(sid: str) -> Optional[Dict[str, Any]]:
    if not sid:
        return None
    if REDIS_CLIENT:
        obj = redis_get_json(research_key(sid))
        if obj:
            return obj
    with STATE_LOCK:
        return INMEM_RESEARCH.get(sid)

def save_research(obj: Dict[str, Any]) -> None:
    sid = obj.get("session_id", "")
    uid = obj.get("user_id", "")
    if not sid or not uid:
        return
    obj["updated_at"] = now_iso()
    if REDIS_CLIENT:
        redis_set_json(research_key(sid), obj, SESSION_TTL_SECONDS)
        redis_sadd(user_research_key(uid), sid, SESSION_TTL_SECONDS)
    with STATE_LOCK:
        INMEM_RESEARCH[sid] = obj

def list_user_research(user_id: str) -> List[Dict[str, Any]]:
    sess: Dict[str, Dict[str, Any]] = {}
    if REDIS_CLIENT:
        ids = redis_smembers(user_research_key(user_id))
        for sid in ids:
            obj = redis_get_json(research_key(sid))
            if obj and obj.get("user_id") == user_id:
                sess[sid] = obj
    with STATE_LOCK:
        for sid, s in INMEM_RESEARCH.items():
            if s.get("user_id") == user_id and sid not in sess:
                sess[sid] = s
    out = list(sess.values())
    def keyfn(x: Dict[str, Any]) -> str:
        return str(x.get("updated_at") or x.get("created_at") or "")
    out.sort(key=keyfn, reverse=True)
    return out[:200]

def validate_message(msg: Any) -> str:
    s = str(msg or "").strip()
    if not s:
        raise ValueError("Üzenet szükséges")
    if len(s) > MAX_MESSAGE_CHARS:
        raise ValueError("Üzenet túl hosszú")
    return s

def validate_goal(goal: Any) -> str:
    s = str(goal or "").strip()
    if not s:
        raise ValueError("Kutatási cél szükséges")
    if len(s) < 5:
        raise ValueError("Kutatási cél túl rövid")
    if len(s) > MAX_GOAL_CHARS:
        raise ValueError("Kutatási cél túl hosszú")
    return s

def save_upload(file_storage) -> Dict[str, Any]:
    if not file_storage or not getattr(file_storage, "filename", ""):
        raise ValueError("Nincs fájl kiválasztva")
    name = secure_filename(file_storage.filename)
    file_storage.stream.seek(0, os.SEEK_END)
    size = file_storage.stream.tell()
    file_storage.stream.seek(0)
    if size <= 0 or size > MAX_UPLOAD_BYTES:
        raise ValueError("Fájl túl nagy")
    stored = f"{uuid.uuid4().hex}_{name}"
    path = os.path.join(UPLOAD_FOLDER, stored)
    file_storage.save(path)
    content = file_read_limited(path, 20000)
    return {"filename": file_storage.filename, "stored_filename": stored, "path": path, "size": int(size), "content_preview": content}

def exa_headers() -> Dict[str, str]:
    return {"x-api-key": EXA_API_KEY, "Content-Type": "application/json"}

def xai_headers() -> Dict[str, str]:
    return {"Authorization": f"Bearer {XAI_API_KEY}", "Content-Type": "application/json"}

def require_config_or_raise() -> None:
    if not EXA_API_KEY:
        raise RuntimeError("EXA_API_KEY nincs beállítva")
    if not XAI_API_KEY and not CEREBRAS_API_KEY:
        raise RuntimeError("XAI_API_KEY vagy CEREBRAS_API_KEY szükséges")

def http_post_json(url: str, headers: Dict[str, str], payload: Dict[str, Any], timeout: float, stream: bool = False) -> requests.Response:
    return requests.post(url, headers=headers, json=payload, timeout=timeout, stream=stream)

def exa_search(query: str, deep: bool = True, num_results: int = FIXED_SEARCH_HITS) -> List[Dict[str, Any]]:
    if not EXA_API_KEY:
        return []
    t = "deep" if deep else "auto"
    payload = {
        "query": query,
        "numResults": int(num_results),
        "type": t,
        "text": True,
        "livecrawl": "always",
        "highlights": {"numSentences": 10, "highlightsPerUrl": 5},
    }
    url = EXA_BASE_URL.rstrip("/") + EXA_SEARCH_PATH
    for attempt in range(3):
        try:
            r = http_post_json(url, exa_headers(), payload, timeout=60, stream=False)
            if r.status_code == 429 or r.status_code >= 500:
                time.sleep((2 ** attempt) * 1.5)
                continue
            if r.status_code != 200:
                return []
            data = r.json()
            res = data.get("results", [])
            if isinstance(res, list):
                return res
            return []
        except Exception:
            time.sleep((2 ** attempt) * 1.5)
    return []

def exa_contents(ids: List[str]) -> List[Dict[str, Any]]:
    if not EXA_API_KEY or not ids:
        return []
    payload = {"ids": ids, "text": True, "livecrawl": "always", "highlights": {"numSentences": 10, "highlightsPerUrl": 10}}
    url = EXA_BASE_URL.rstrip("/") + EXA_CONTENTS_PATH
    for attempt in range(3):
        try:
            r = http_post_json(url, exa_headers(), payload, timeout=60, stream=False)
            if r.status_code == 429 or r.status_code >= 500:
                time.sleep((2 ** attempt) * 1.5)
                continue
            if r.status_code != 200:
                return []
            data = r.json()
            res = data.get("results", [])
            if isinstance(res, list):
                return res
            return []
        except Exception:
            time.sleep((2 ** attempt) * 1.5)
    return []

def exa_find_similar(url_in: str, num_results: int = 20) -> List[Dict[str, Any]]:
    if not EXA_API_KEY or not url_in:
        return []
    payload = {"url": url_in, "numResults": int(num_results), "text": True, "livecrawl": "always"}
    url = EXA_BASE_URL.rstrip("/") + EXA_FIND_SIMILAR_PATH
    for attempt in range(3):
        try:
            r = http_post_json(url, exa_headers(), payload, timeout=60, stream=False)
            if r.status_code == 429 or r.status_code >= 500:
                time.sleep((2 ** attempt) * 1.5)
                continue
            if r.status_code != 200:
                return []
            data = r.json()
            res = data.get("results", [])
            if isinstance(res, list):
                return res
            return []
        except Exception:
            time.sleep((2 ** attempt) * 1.5)
    return []

def xai_chat_complete(messages: List[Dict[str, Any]], model: str, max_tokens: int, temperature: float) -> str:
    if not XAI_API_KEY:
        raise RuntimeError("XAI_API_KEY nincs beállítva")
    payload = {
        "model": model,
        "messages": messages,
        "max_tokens": int(max_tokens),
        "temperature": float(temperature),
        "stream": False,
    }
    url = XAI_BASE_URL.rstrip("/") + XAI_CHAT_PATH
    for attempt in range(3):
        try:
            r = http_post_json(url, xai_headers(), payload, timeout=180, stream=False)
            if r.status_code == 429 or r.status_code >= 500:
                time.sleep((2 ** attempt) * 1.5)
                continue
            if r.status_code != 200:
                raise RuntimeError(f"xAI hiba {r.status_code}")
            data = r.json()
            return str(data["choices"][0]["message"]["content"])
        except Exception:
            if attempt == 2:
                raise
            time.sleep((2 ** attempt) * 1.5)
    raise RuntimeError("xAI hívás sikertelen")

def xai_chat_stream(messages: List[Dict[str, Any]], model: str, max_tokens: int, temperature: float) -> Iterable[str]:
    if not XAI_API_KEY:
        raise RuntimeError("XAI_API_KEY nincs beállítva")
    payload = {
        "model": model,
        "messages": messages,
        "max_tokens": int(max_tokens),
        "temperature": float(temperature),
        "stream": True,
    }
    url = XAI_BASE_URL.rstrip("/") + XAI_CHAT_PATH
    r = http_post_json(url, xai_headers(), payload, timeout=180, stream=True)
    if r.status_code != 200:
        raise RuntimeError(f"xAI stream hiba {r.status_code}")
    for line in r.iter_lines():
        if not line:
            continue
        try:
            txt = line.decode("utf-8", errors="ignore")
        except Exception:
            continue
        if not txt.startswith("data: "):
            continue
        chunk = txt[6:].strip()
        if chunk == "[DONE]":
            break
        try:
            obj = json.loads(chunk)
        except Exception:
            continue
        try:
            delta = obj.get("choices", [{}])[0].get("delta", {})
            c = delta.get("content")
            if c:
                yield str(c)
        except Exception:
            continue

def cerebras_client():
    from cerebras.cloud.sdk import Cerebras
    if not CEREBRAS_API_KEY:
        raise RuntimeError("CEREBRAS_API_KEY nincs beállítva")
    return Cerebras(api_key=CEREBRAS_API_KEY)

def cerebras_chat_complete(messages: List[Dict[str, Any]], model: str, max_tokens: int, temperature: float, top_p: float) -> str:
    client = cerebras_client()
    for attempt in range(3):
        try:
            resp = client.chat.completions.create(
                model=model,
                max_tokens=int(max_tokens),
                messages=messages,
                temperature=float(temperature),
                top_p=float(top_p),
            )
            ch = resp.choices[0].message.content if resp.choices else ""
            return str(ch or "")
        except Exception:
            if attempt == 2:
                raise
            time.sleep((2 ** attempt) * 1.5)
    return ""

def cerebras_chat_stream(messages: List[Dict[str, Any]], model: str, max_tokens: int, temperature: float, top_p: float) -> Iterable[str]:
    client = cerebras_client()
    stream = client.chat.completions.create(
        model=model,
        max_tokens=int(max_tokens),
        messages=messages,
        temperature=float(temperature),
        top_p=float(top_p),
        stream=True,
    )
    for chunk in stream:
        try:
            delta = chunk.choices[0].delta
            c = getattr(delta, "content", None)
            if c:
                yield str(c)
        except Exception:
            continue

def simple_complexity_score(text: str) -> int:
    t = (text or "").strip().lower()
    if not t:
        return 1
    length = len(t)
    score = 1
    if length > 120:
        score += 1
    if length > 400:
        score += 2
    keywords = [
        "bizonyítsd", "prove", "derive", "differenciál", "integrál", "quantum", "formális", "komplex",
        "optimalizál", "paralel", "párhuzam", "statisztika", "regresszió", "kísérlet", "módszertan",
        "rendszerterv", "architektúra", "threat model", "biztonság", "compliance", "hipotézis",
        "forráskritika", "meta-analízis", "benchmark",
    ]
    hits = sum(1 for k in keywords if k in t)
    score += min(6, hits)
    if "?" in t and hits == 0 and length < 80:
        score = max(1, score - 1)
    return max(1, min(10, score))

def build_agent_roles(n: int) -> List[str]:
    base = ["reasoner", "researcher", "critic", "creator", "validator"]
    out: List[str] = []
    while len(out) < n:
        for r in base:
            out.append(r)
            if len(out) >= n:
                break
    return out

