        {"title": "Kivonatolás", "description": "A legrelevánsabb tartalmak összegyűjtése és tömörítése a további elemzéshez."},
        {"title": "Elemzés", "description": "Konzisztens állítások, ellentmondások, kockázatok és alternatív értelmezések feltárása."},
        {"title": "Jelentés", "description": "Strukturált, részletes kutatási jelentés elkészítése, a forrásokra támaszkodva."},
    ]
    return base

def llm_plan_goal(goal: str) -> List[Dict[str, str]]:
    if not XAI_API_KEY:
        return plan_from_goal(goal)
    sys = "Végig magyarul válaszolj. Készíts kutatási tervet. Válaszolj kizárólag JSON-ben: {\"plan\":[{\"title\":\"...\",\"description\":\"...\"}, ...]}. Legyen 6-10 lépés."
    msg = [{"role": "system", "content": sys}, {"role": "user", "content": f"Kutatási cél: {goal}"}]
    try:
        out = xai_chat_complete(msg, XAI_MODEL_PRO, max_tokens=1200, temperature=0.2)
        m = None
        try:
            m = json.loads(out)
        except Exception:
            s = out.strip()
            i = s.find("{")
            j = s.rfind("}")
            if i >= 0 and j > i:
                m = json.loads(s[i : j + 1])
        if isinstance(m, dict) and isinstance(m.get("plan"), list):
            plan = []
            for step in m["plan"]:
                if isinstance(step, dict) and step.get("title") and step.get("description"):
                    plan.append({"title": str(step["title"])[:120], "description": str(step["description"])[:500]})
            if plan:
                return plan[:12]
    except Exception:
        pass
    return plan_from_goal(goal)

def exa_query_set(goal: str) -> List[str]:
    g = goal.strip()
    qs = [
        g,
        f"{g} áttekintés",
        f"{g} összehasonlítás",
        f"{g} kockázatok",
        f"{g} best practices",
        f"{g} case study",
        f"{g} security privacy",
        f"{g} architecture design",
        f"{g} implementation details",
        f"{g} monitoring observability",
    ]
    seen = set()
    out = []
    for q in qs:
        q2 = " ".join(q.split())
        if q2 and q2 not in seen:
            seen.add(q2)
            out.append(q2)
    return out[:25]

