def pick_top_urls(results: List[Dict[str, Any]], n: int) -> List[str]:
    items = []
    for r in results:
        u = str(r.get("url", "") or "")
        sc = r.get("score", 0.0)
        try:
            scv = float(sc)
        except Exception:
            scv = 0.0
        if u.startswith("http"):
            items.append((scv, u))
    items.sort(key=lambda x: x[0], reverse=True)
    out = []
    seen = set()
    for _, u in items:
        if u in seen:
            continue
        seen.add(u)
        out.append(u)
        if len(out) >= n:
            break
    return out

def run_research_background(session_id: str) -> None:
    cleanup_tick()
    sess = load_research(session_id)
    if not sess:
        return
    try:
        require_config_or_raise()
        research_set_status(sess, "planning", 5.0, "Kutatási terv készítése")
        plan = llm_plan_goal(sess["goal"])
        sess["plan"] = plan
        save_research(sess)
        broadcast_sse(session_id, {"type": "orchestratorplan", "plan": plan, "progress": 10})
        research_set_status(sess, "exasearching", 12.0, "Forrásgyűjtés (Exa)")
        queries = exa_query_set(sess["goal"])
        seen_urls = set()
        sources: List[Dict[str, Any]] = []
        total_queries = len(queries)
        for i, q in enumerate(queries):
            if len(sources) >= 1500:
                break
            broadcast_sse(session_id, {"type": "exabatchstarted", "query": q[:200], "queryindex": i + 1, "totalqueries": total_queries, "sourcessofar": len(sources)})
            res = exa_search(q, deep=True, num_results=FIXED_SEARCH_HITS)
            added = 0
            for r in res:
                u = str(r.get("url", "") or "")
                if not u or u in seen_urls:
                    continue
                seen_urls.add(u)
                sources.append({
                    "url": u,
                    "title": str(r.get("title", "") or "")[:300],
                    "text": str(r.get("text", "") or "")[:8000],
                    "publishedDate": r.get("publishedDate"),
                    "score": r.get("score", 0.0),
                    "highlights": r.get("highlights", []),
                })
                added += 1
                if len(sources) >= 1500:
                    break
            broadcast_sse(session_id, {"type": "exabatchcompleted", "queryindex": i + 1, "newsources": added, "totalsources": len(sources)})
            progress = 12.0 + ((i + 1) / max(1, total_queries)) * 35.0
            sess["progress"] = min(47.0, progress)
            save_research(sess)
            time.sleep(0.25)
            if len(sources) > 200 and (i % 4 == 3):
                top_urls = pick_top_urls(res, 5)
                for tu in top_urls:
                    sim = exa_find_similar(tu, num_results=20)
                    for r2 in sim:
                        u2 = str(r2.get("url", "") or "")
                        if not u2 or u2 in seen_urls:
                            continue
                        seen_urls.add(u2)
                        sources.append({
                            "url": u2,
                            "title": str(r2.get("title", "") or "")[:300],
                            "text": str(r2.get("text", "") or "")[:6000],
                            "publishedDate": r2.get("publishedDate"),
                            "score": r2.get("score", 0.0),
                            "highlights": r2.get("highlights", []),
                        })
                        if len(sources) >= 1500:
                            break
                    if len(sources) >= 1500:
                        break
        sess["sources"] = sources
        save_research(sess)
        broadcast_sse(session_id, {"type": "exacomplete", "totalsources": len(sources), "progress": 45})
        research_set_status(sess, "reportplanning", 50.0, "Jelentés vázlat")
        outline = []
