            outline.append({"section_id": f"sec_{idx+1}", "title": step["title"], "target_words": 6000, "key_points": [step["description"]], "sources_to_cite": 10})
        broadcast_sse(session_id, {"type": "reportoutlineready", "sectionscount": len(outline), "progress": 55})
        research_set_status(sess, "reportwriting", 55.0, "Jelentés írása")
        goal = sess["goal"]
        upload_context = merge_context_from_uploads(sess.get("uploads", []))
        max_sections = min(12, len(outline))
        picked_sources = sources[:400]
        sources_text_blocks = []
        for i, s in enumerate(picked_sources[:60]):
            tt = str(s.get("title", "") or "")[:160]
            uu = str(s.get("url", "") or "")[:260]
