            broadcast_sse(session_id, {"type": "reportsegmentcompleted", "segmentindex": si + 1, "sectiontitle": sec["title"], "wordswritten": len((text_out or "").split()), "progress": 55 + ((si + 1) / max_sections) * 35})
            time.sleep(0.3)
        research_set_status(sess, "reportcompiling", 92.0, "Végső jelentés összeállítása")
        sources_list_parts = []
