        sess["report_size"] = len(final_report.encode("utf-8", errors="ignore"))
        sess["final_response"] = final_report[:12000]
        sess["metrics"]["end_ts"] = time.time()
        research_set_status(sess, "completed", 100.0, "Kutatás kész")
        save_research(sess)
        broadcast_sse(session_id, {
            "type": "researchcomplete",
            "finalresponse": sess["final_response"],
            "reportpath": filename,
            "reportsizekb": int(sess["report_size"] // 1024),
            "totalsources": len(sources),
            "sectionscount": max_sections,
