        return redirect("/?error=no_auth_code")
    expected = session.get("oauth_state", "")
    if expected and state and not timing_safe_equal(str(expected), str(state)):
        return redirect("/?error=state_mismatch")
    if not (KINDE_HOST and KINDE_CLIENT_ID and KINDE_CLIENT_SECRET and KINDE_REDIRECT_URI):
        return redirect("/?error=server_config")
    token_url = f"{KINDE_HOST.rstrip('/')}/oauth2/token"
    try:
        tr = requests.post(
            token_url,
            data={
                "grant_type": "authorization_code",
                "code": code,
                "redirect_uri": KINDE_REDIRECT_URI,
                "client_id": KINDE_CLIENT_ID,
                "client_secret": KINDE_CLIENT_SECRET,
            },
            timeout=DEFAULT_HTTP_TIMEOUT,
        )
    except Exception:
        return redirect("/?error=token_failed")
    if tr.status_code != 200:
        return redirect("/?error=token_failed")
    tokens = tr.json()
    access_token = tokens.get("access_token", "")
    if not access_token:
        return redirect("/?error=token_failed")
    profile_url = f"{KINDE_HOST.rstrip('/')}/oauth2/v2/user_profile"
    try:
        pr = requests.get(profile_url, headers={"Authorization": f"Bearer {access_token}"}, timeout=DEFAULT_HTTP_TIMEOUT)
    except Exception:
        return redirect("/?error=profile_failed")
    if pr.status_code != 200:
        return redirect("/?error=profile_failed")
    ud = pr.json()
    uid = str(ud.get("sub") or "")
    email = ud.get("email")
    name = ud.get("name") or (str(email).split("@")[0] if email else "Felhasználó")
    pic = ud.get("picture")
    session["user"] = {"id": uid, "email": email, "name": name, "picture": pic, "is_guest": False}
    session["access_token"] = access_token
    session.permanent = True
    return redirect("/loginpopup")

