@app.route("/api/chat/stream", methods=["POST"])
def api_chat_stream():
    r = require_user()
    if r:
        return r
    user = ensure_user()
    allowed, remaining, limit = rate_limit_check(user)
    if not allowed:
        return jsonify({"error": "Rate limit exceeded", "remaining": remaining, "limit": limit}), 429
    try:
        message = validate_message(request.form.get("message", ""))
        conversation_id = str(request.form.get("conversationid", "") or request.form.get("conversation_id", "") or "").strip()
        uploads: List[Dict[str, Any]] = []
        files = request.files.getlist("files")
        if files:
            for f in files[:5]:
                uploads.append(save_upload(f))
    except Exception as e:
        return jsonify({"error": str(e)}), 400
    conv = None
    if not conversation_id:
        conv = make_conversation(user["id"], message)
        conversation_id = conv["id"]
    else:
        conv = load_conversation(conversation_id)
        if not conv:
            return jsonify({"error": "Conversation not found"}), 404
        if conv.get("user_id") != user["id"]:
            return jsonify({"error": "Access denied"}), 403
    conversation_append(conv, "user", message)
    upload_context = merge_context_from_uploads(uploads)
    sys = build_chat_system_prompt()
    if upload_context:
        sys = sys + "\n\nFeltöltött fájl kontextus:\n" + upload_context
    messages_for_api: List[Dict[str, Any]] = [{"role": "system", "content": sys}]
    for m in (conv.get("messages", []) or [])[-20:]:
        if m.get("role") in ("user", "assistant") and m.get("content"):
            messages_for_api.append({"role": m["role"], "content": str(m["content"])})
    use_xai = bool(XAI_API_KEY)
    use_cerebras = bool(CEREBRAS_API_KEY)
    if not use_xai and not use_cerebras:
        return jsonify({"error": "Nincs beállítva LLM kulcs"}), 503
    complexity = simple_complexity_score(message)
    pro_mode = (complexity > 5 and use_xai)
    model = XAI_MODEL_PRO if pro_mode else XAI_MODEL_FAST
    def generate():
        yield sse_pack({"type": "start", "conversationid": conversation_id})
        full: List[str] = []
        try:
            if use_xai:
                for tok in xai_chat_stream(messages_for_api, model=model, max_tokens=2000, temperature=0.4 if pro_mode else 0.7):
                    full.append(tok)
                    yield sse_pack({"type": "token", "content": tok})
            else:
                for tok in cerebras_chat_stream(messages_for_api, model=CEREBRAS_MODEL_FAST, max_tokens=2000, temperature=0.9, top_p=0.9):
                    full.append(tok)
                    yield sse_pack({"type": "token", "content": tok})
        except Exception as e:
            yield sse_pack({"type": "error", "message": str(e)})
            return
        resp = "".join(full).strip()
        conversation_append(conv, "assistant", resp)
        save_conversation(conv)
        yield sse_pack({"type": "done", "conversationid": conversation_id, "remaining": remaining, "limit": limit})
    return Response(stream_with_context(generate()), mimetype="text/event-stream", headers={"Cache-Control": "no-cache", "Connection": "keep-alive", "X-Accel-Buffering": "no"})

