@app.route("/api/research/<session_id>/events", methods=["GET"])
def api_research_events(session_id: str):
    r = require_user()
    if r:
        return r
    user = ensure_user()
    sess = load_research(session_id)
    if not sess:
        return jsonify({"error": "Not found"}), 404
    if sess.get("user_id") != user["id"]:
        return jsonify({"error": "Access denied"}), 403
    q = sse_register(session_id)
    if not q:
        return jsonify({"error": "Too many SSE clients"}), 429
    def event_stream():
        yield sse_pack({"type": "statusupdate", "phase": "Kapcsolódva", "progress": float(sess.get("progress", 0.0))})
        try:
            while True:
                try:
                    item = q.get(timeout=25)
                except queue.Empty:
                    yield ": keep-alive\n\n"
                    continue
                yield sse_pack(item)
        finally:
            sse_unregister(session_id, q)
    return Response(stream_with_context(event_stream()), mimetype="text/event-stream", headers={"Cache-Control": "no-cache", "Connection": "keep-alive", "X-Accel-Buffering": "no"})

